  "claims": [
    {
      "claim_id": "C1",
      "text": "Consolidated Sales and Revenues increased by 4.29% from $64,809 million in 2024 to $67,589 million in 2025 (filing reports rounded 4%).",
      "evidence_ids": [
        "EP_0014_E01"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0014_F02",
        "to_fact_id": "EP_0014_F01",
        "metric": "revenue",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "4.29",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C2",
      "text": "Despite the increase in revenue, Consolidated Operating Profit decreased by 14.70% (calculated; filing reports rounded 15%) from $13,072 million in 2024 to $11,151 million in 2025.",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0014_F04",
        "to_fact_id": "EP_0014_F03",
        "metric": "operating_profit",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "-14.70",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C3",
      "text": "The decrease in operating profit was primarily due to unfavorable manufacturing costs of $2,148 million and unfavorable price realization of $817 million, partially offset by the profit impact of higher sales volume of $1,218 million (Item 7, EP_0014_E02).",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": null
    },
    {
      "claim_id": "C4",
      "text": "The operating profit margin declined from 20.2 percent in 2024 to 16.5 percent in 2025 (Item 7, EP_0014_E02).",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": null
    },
    {
      "claim_id": "C5",
      "text": "The SEGMENT_33 segment's profit decreased by 24.17% (calculated; filing reports rounded (24%)) from $6,165 million in 2024 to $4,675 million in 2025, contributing significantly to the overall decline in operating profit.",
      "evidence_ids": [
        "EP_0014_E02"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0014_F06",
        "to_fact_id": "EP_0014_F05",
        "metric": "construction_industries_profit",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "-24.17",
        "unit": "percent"
      }
    }
  ],
  "rationale": "Consolidated sales and revenues grew modestly by 4.29% in 2025, while consolidated operating profit declined significantly by 14.70% and operating profit margin contracted 370 basis points from 20.2% to 16.5%. The profit decline was driven by unfavorable manufacturing costs ($2.148 billion, largely tariff-related) and unfavorable price realization ($817 million), partially offset by higher sales volume. The SEGMENT_33 segment saw a 24.17% profit decline, contributing heavily to the overall drop. The risk of more restrictive trade policies and higher tariffs noted in Item 1A could further pressure manufacturing costs and profitability, supporting a SELL recommendation."
}

